import { orderManualEntries, type ManualEntry } from './manual-order';

/**
 * Number of pages an autogenerated sidebar group links for `directory`: same filter and order as
 * the sidebar (pages in the directory that are not hidden), so the home counts match it.
 */
export function sectionPageCount(entries: readonly ManualEntry[], directory: string): number {
	return orderManualEntries(entries, [{ label: directory, kind: 'chapter', directory }]).length;
}

/** «N páginas», or «1 página» for a single page. */
export function pagesLabel(count: number): string {
	return count === 1 ? '1 página' : `${count} páginas`;
}
